cat >> src/orchestration/orchestratorHelpers.test.ts <<'EOF'

describe('addRoundUsage', () => {
  it('sums each token field across rounds and skips rounds that reported nothing', () => {
    const first = addRoundUsage(undefined, {inputTokens: 2, outputTokens: 1, totalTokens: 3});
    const gap = addRoundUsage(first, undefined);

    expect(addRoundUsage(gap, {inputTokens: 7, outputTokens: 4, totalTokens: 11})).toEqual({
      inputTokens: 9,
      outputTokens: 5,
      totalTokens: 14,
    });
  });

  it('stays undefined when no round reported usage', () => {
    expect(addRoundUsage(addRoundUsage(undefined, undefined), undefined)).toBeUndefined();
  });
});
EOF
